\label{def:biased_compression}
A (possibly) stochastic mapping $\mathcal{C}\,:\,\mathbb{R}^d \rightarrow \mathbb{R}^d$ is a \textit{biased  compressor} if
there exists $\alpha \in (0,1]$ such that
\begin{align}
    \label{eq:biased_compressor}
    \qquad \Exp{\norm{\mathcal{C}(x) - x}^2} \leq (1 - \alpha) \norm{x}^2, \qquad \forall x \in \mathbb{R}^d.
\end{align}

\begin{align}
      \label{eq:biased_compressor}
      \qquad \Exp{\norm{\mathcal{C}(x) - x}^2} \leq (1 - \alpha) \norm{x}^2, \qquad \forall x \in \mathbb{R}^d.
  \end{align}

\label{def:unbiased_compression}
A stochastic mapping $\mathcal{C}\,:\,\mathbb{R}^d \rightarrow \mathbb{R}^d$ is an \textit{unbiased compressor} if
there exists $\omega \geq 0$ such that
\begin{align}
    \label{eq:compressor}
    \Exp{\mathcal{C}(x)} = x, \qquad \Exp{\norm{\mathcal{C}(x) - x}^2} \leq \omega \norm{x}^2, \qquad \forall x \in \mathbb{R}^d.
\end{align}

\begin{align}
      \label{eq:compressor}
      \Exp{\mathcal{C}(x)} = x, \qquad \Exp{\norm{\mathcal{C}(x) - x}^2} \leq \omega \norm{x}^2, \qquad \forall x \in \mathbb{R}^d.
  \end{align}

Instead of $\mathfrak{m}^{{\scriptscriptstyle \textnormal{w2s}}}_{{\scriptscriptstyle \mathcal{M}}},$ methods performing bidirectional compression attempt to minimize \emph{the total communication complexity}, which we define as a convex combination of the w2s and s2w communication complexities:
\begin{align}
  \label{eq:main_complexity}
  \mathfrak{m}^{r}_{{\scriptscriptstyle \mathcal{M}}} := (1 - r)\mathfrak{m}^{{\scriptscriptstyle \textnormal{w2s}}}_{{\scriptscriptstyle \mathcal{M}}} + r \mathfrak{m}^{{\scriptscriptstyle \textnormal{s2w}}}_{{\scriptscriptstyle \mathcal{M}}}.
\end{align}

\begin{align}
  \label{eq:main_complexity}
  \mathfrak{m}^{r}_{{\scriptscriptstyle \mathcal{M}}} := (1 - r)\mathfrak{m}^{{\scriptscriptstyle \textnormal{w2s}}}_{{\scriptscriptstyle \mathcal{M}}} + r \mathfrak{m}^{{\scriptscriptstyle \textnormal{s2w}}}_{{\scriptscriptstyle \mathcal{M}}}.
\end{align}

\caption{\algname{2Direction}: A Fast Gradient Method Supporting Bidirectional Compression} 
\label{alg:bi_diana}
\footnotesize
\begin{algorithmic}[1]
\STATE \textbf{Parameters:} Lipschitz-like parameter $\bar{L} > 0$, strong-convexity parameter $\mu \geq 0,$ probability $p \in (0, 1],$ parameter $\Gamma_0 \geq 1$, momentum $\tau \in (0, 1],$ contraction parameter $\alpha \in (0, 1]$ from \eqref{eq:biased_compressor}, initial point $x^0 \in \mathbb{R}^d,$ initial gradient shifts $h^0_1, \dots , h^0_n\in \mathbb{R}^d,$ gradient shifts $k^0 \in \mathbb{R}^d$ and $v^0 \in \mathbb{R}^d$
\STATE Initialize $\beta = \nicefrac{1}{(\omega + 1)},$ $w^0 = z^0 = u^0 = x^0,$ and $h^0 = \frac{1}{n}\sum_{i = 1}^n h_i^0$
\FOR{$t = 0, 1, \dots, T - 1$} 
\STATE $\Gamma_{t+1}, \gamma_{t+1}, \theta_{t+1}= \textnormal{CalculateLearningRates}(\Gamma_t, \bar{L}, \mu, p, \alpha, \tau, \beta)$ \hfill{\scriptsize \color{gray} Get learning rates using Algorithm~\ref{alg:learning_rates}}
\FOR{$i = 1, \dots, n$ in parallel}
\STATE $y^{t+1} = \theta_{t+1} {\color{mydarkgreen} w^t} + (1 - \theta_{t+1}) z^t$ \label{line:bi_diana:y}
\STATE $m_i^{t,y} = \mathcal{C}_i^{D, y}(\nabla f_i(y^{t+1}) - h_i^t)$  
\hfill{\scriptsize \color{gray} Worker $i$ compresses the shifted gradient via the compressor $\mathcal{C}_i^{D, y} \in \mathbb{U}(\omega)$}
\STATE {Send compressed message $m_i^{t,y}$ to the server}
\ENDFOR
\STATE $g^{t+1} = h^t + \frac{1}{n}\sum_{i=1}^n m_i^{t,y}$ 
\STATE $u^{t+1} = arg\,min_{x \in \mathbb{R}^d} \inp{g^{t+1}}{x} + \frac{\bar{L} + \Gamma_{t} \mu}{2 \gamma_{t+1}} \norm{x - u^t}^2 + \frac{\mu}{2} \norm{x - y^{t+1}}^2$ \hfill{\scriptsize \color{gray} A gradient-like descent step}
\STATE {\color{mydarkgreen} $q^{t+1} = arg\,min_{x \in \mathbb{R}^d} \inp{k^t}{x} + \frac{\bar{L} + \Gamma_{t} \mu}{2 \gamma_{t+1}} \norm{x - w^t}^2 + \frac{\mu}{2} \norm{x - y^{t+1}}^2$} \label{line:bi_diana:q}
\STATE {\color{mydarkgreen} $p^{t+1} = \mathcal{C}^{P}\left(u^{t+1} - q^{t+1}\right)$}  \hfill {\scriptsize \color{gray} Server compresses the shifted model via the compressor $\mathcal{C}^{P} \in \mathbb{B}\left(\alpha\right)$} \label{line:bi_diana:p}
\STATE {\color{mydarkgreen} $w^{t+1} = q^{t+1} + p^{t+1}$} \label{line:bi_diana:w}
\STATE $x^{t+1} = \theta_{t+1} u^{t+1} + (1 - \theta_{t+1}) z^t$
\STATE {\color{mydarkgreen} Send compressed message $p^{t+1}$ to all $n$ workers} \label{line:bi_diana:broadcast_compr}
\STATE Flip a coin $c^t \sim \textnormal{Bernoulli}(p)$
\STATE {\color{mydarkgreen} $k^{t+1} = \begin{cases}
  v^{t}, &c^t = 1 \\
  k^{t}, &c^t = 0
\end{cases}$} \quad and \quad $z^{t+1} = \begin{cases}
  x^{t+1}, &c^t = 1 \\
  z^{t}, &c^t = 0
\end{cases}$ \label{line:bi_diana:k}
\IF{$c^t = 1$}
\STATE {\color{mydarkgreen} Broadcast non-compressed messages $x^{t+1}$ and $k^{t+1}$ to all $n$ workers} \hfill{\scriptsize \color{gray} With small probability $p$!} \label{line:bi_diana:broadcast}
\ENDIF
\FOR{$i = 1, \dots, n$ in parallel}
\STATE {\color{mydarkgreen} $q^{t+1} = arg\,min_{x \in \mathbb{R}^d} \inp{k^t}{x} + \frac{\bar{L} + \Gamma_{t} \mu}{2 \gamma_{t+1}} \norm{x - w^t}^2 + \frac{\mu}{2} \norm{x - y^{t+1}}^2$} \hfill{\scriptsize \color{gray}} \label{line:bi_diana:q_local}
\STATE {\color{mydarkgreen} $w^{t+1} = q^{t+1} + p^{t+1}$} \label{line:bi_diana:w_local}
\STATE $z^{t+1} = \begin{cases}
  x^{t+1}, &c^t = 1 \\
  z^{t}, &c^t = 0
\end{cases}$
\STATE $m_i^{t,z} = \mathcal{C}_i^{D, z}(\nabla f_i(z^{t+1}) - h_i^t)$  \hfill{\scriptsize \color{gray} Worker $i$ compresses the shifted gradient via the compressor $\mathcal{C}_i^{D, z} \in \mathbb{U}(\omega)$}
\STATE $h_i^{t+1} = h_i^t + \beta m_i^{t,z}$ 
\STATE {Send compressed message $m_i^{t,z}$ to the server}
\ENDFOR
{\color{mydarkgreen} \STATE $v^{t+1} = (1 - \tau) v^{t} + \tau \left(h^t + \frac{1}{n} \sum_{i=1}^n m_i^{t,z}\right)$} \label{line:bi_diana:v}
\STATE $h^{t+1} = h^t + \beta \frac{1}{n} \sum_{i=1}^n m_i^{t,z}$ 
\ENDFOR
\end{algorithmic}

\caption{CalculateLearningRates}
\label{alg:learning_rates}
\footnotesize
\begin{algorithmic}[1]
  \STATE \textbf{Parameters:} element $\Gamma_t$; parameter $\bar{L} > 0$; strong-convexity parameter $\mu \geq 0,$ probability $p,$ contraction parameter $\alpha$, momentum $\tau$, parameter $\beta$
  \STATE Find the largest root $\bar{\theta}_{t+1}$ of the quadratic equation $$p \bar{L} \Gamma_t \bar{\theta}^2_{t+1} + p (\bar{L} + \Gamma_t \mu) \bar{\theta}_{t+1} - (\bar{L} + \Gamma_t \mu) = 0$$ \label{line:learning_rates:root}
  \STATE $\theta_{\min} = \frac{1}{4}\min\left\{1, \frac{\alpha}{p}, \frac{\tau}{p}, \frac{\beta}{p}\right\}$; \quad $\theta_{t+1} = \min\{\bar{\theta}_{t+1}, \theta_{\min}\}$; \quad$\gamma_{t+1} = \frac{p \theta_{t+1} \Gamma_t}{1 - p \theta_{t+1}}$; \quad$\Gamma_{t+1} = \Gamma_{t} + \gamma_{t+1}$
\end{algorithmic}

