    \label{eq:abstract_comm_complexity}
    \mathfrak{m}^{{\scriptscriptstyle \textnormal{w2s}}}_{{\scriptscriptstyle \textnormal{new}}} = \widetilde{\Theta}\left(K_{\omega} \times T + d\right) \quad\textnormal{ and } \quad \mathfrak{m}^{{\scriptscriptstyle \textnormal{s2w}}}_{{\scriptscriptstyle \textnormal{new}}} = \widetilde{\Theta}\left(\left(K_{\alpha} + p d\right) \times T + d\right).
  \end{align}

\begin{align}
      \label{eq:realistic_compl}
 \textstyle     T^{\textnormal{realistic}} &\textstyle := \widetilde{\Theta}\Bigg(\max\Bigg\{\sqrt{\frac{L \max\{\omega + 1, \mu^r_{\omega, \alpha}\}}{\alpha \mu}},\sqrt{\frac{L_{\max} \omega \max\{\omega + 1, \mu^r_{\omega, \alpha}\}}{n \mu}}, \frac{1}{\alpha}, (\omega + 1), \mu^r_{\omega, \alpha}\Bigg\}\Bigg).
    \end{align}

  \label{cor:optimistic}
Choose $r \in [0, 1],$ and let $\mu^r_{\omega, \alpha} := \frac{rd}{(1 - r) K_{\omega} + r K_{\alpha}}.$ In view of Theorem~\ref{theorem:comm_complexity}, the values $p$ and $\tau$ given by \eqref{eq:opt_p_know} and \eqref{eq:opt_tau_know}, respectively,
    minimize $\mathfrak{m}^{r}_{{\scriptscriptstyle \textnormal{new}}}$ from \eqref{eq:strong_complexity}. This choice leads to the following number of communication rounds:
    {\small 
    \begin{eqnarray}
    \begin{aligned}
      \label{eq:optimistic_compl}
      T^{\textnormal{optimistic}} = \widetilde{\Theta}\Bigg(\max\Bigg\{&\sqrt{\frac{L \max\{1, \mu^r_{\omega, \alpha}\}}{\alpha \mu}}, \sqrt{\frac{L^{2/3} L_{\max}^{1/3} (\omega + 1)}{\alpha n^{1/3} \mu}}, \sqrt{\frac{L^{1/2} L_{\max}^{1/2} (\omega + 1)^{3/2}}{\sqrt{\alpha n} \mu}}, \\
      &\sqrt{\frac{L_{\max} \omega \max\{\omega + 1, \mu^r_{\omega, \alpha}\}}{n \mu}}, \frac{1}{\alpha}, (\omega + 1), \mu^r_{\omega, \alpha}\Bigg\}\Bigg).
    \end{aligned}
    \end{eqnarray}}
    The total communication complexity thus equals $\textstyle\mathfrak{m}^{r}_{{\scriptscriptstyle \textnormal{optimistic}}} = \widetilde{\Theta}\left(\left((1 - r)K_{\omega} + r K_{\alpha}\right) T_{{\scriptscriptstyle \textnormal{optimistic}}} + d\right).$

\begin{eqnarray}
    \begin{aligned}
      \label{eq:optimistic_compl}
      T^{\textnormal{optimistic}} = \widetilde{\Theta}\Bigg(\max\Bigg\{&\sqrt{\frac{L \max\{1, \mu^r_{\omega, \alpha}\}}{\alpha \mu}}, \sqrt{\frac{L^{2/3} L_{\max}^{1/3} (\omega + 1)}{\alpha n^{1/3} \mu}}, \sqrt{\frac{L^{1/2} L_{\max}^{1/2} (\omega + 1)^{3/2}}{\sqrt{\alpha n} \mu}}, \\
      &\sqrt{\frac{L_{\max} \omega \max\{\omega + 1, \mu^r_{\omega, \alpha}\}}{n \mu}}, \frac{1}{\alpha}, (\omega + 1), \mu^r_{\omega, \alpha}\Bigg\}\Bigg).
    \end{aligned}
    \end{eqnarray}

  \label{rem:optimistic}
  To simplify the rate \eqref{eq:optimistic_compl}, let $\mathcal{C}_i^{D, \cdot}$ be the Rand$K$ sparsifier\footnote{It is sufficient to assume that $\omega + 1 = \Theta\left(\nicefrac{d}{K_{\omega}}\right)$.} and consider the case when the s2w communication is not slower than the w2s communication, i.e., $r \leq \nicefrac{1}{2}.$ Then
  {\small$T^{\textnormal{optimistic}} = \widetilde{\Theta}\left(\max\left\{\sqrt{\frac{L \max\{1, r \left(\omega + 1\right)\}}{\alpha \mu}}, \sqrt{\frac{L^{2/3} L_{\max}^{1/3} (\omega + 1)}{\alpha n^{1/3} \mu}}, \sqrt{\frac{L^{1/2} L_{\max}^{1/2} (\omega + 1)^{3/2}}{\sqrt{\alpha n} \mu}}, \sqrt{\frac{L_{\max} \omega (\omega + 1)}{n \mu}}, \frac{1}{\alpha}, (\omega + 1)\right\}\right).$}
Indeed, this follows from $r \leq \nicefrac{1}{2}$ and the fact that $\omega + 1 = \nicefrac{d}{K_{\omega}}$ for the Rand$K$ compressor:
    $\mu^r_{\omega, \alpha} := \frac{rd}{(1 - r) K_{\omega} + r K_{\alpha}} \leq \frac{r}{1 - r} \times \frac{d}{K_{\omega}} \leq 2 r \left(\omega + 1\right)$.

