\caption{Accelerated \algname{DIANA} (\algname{ADIANA}) by \citet{ADIANA}}
\label{alg:adiana}
\footnotesize
\begin{algorithmic}[1]
\STATE \textbf{Parameters:} Lipschitz-like parameter $\bar{L} > 0$, strong-convexity parameter $\mu \geq 0,$ probability $p,$ parameter $\Gamma_0$, initial point $x^0 \in \mathbb{R}^d,$ initial gradient shifts $h^0_1, \dots , h^0_n\in \mathbb{R}^d$
\STATE Initialize $\beta = \nicefrac{1}{\omega + 1}$ and $z^0 = u^0 = x^0$
\STATE Initialize $h^0 = \frac{1}{n}\sum_{i = 1}^n h_i^0$
\FOR{$t = 0, 1, \dots, T - 1$} 
\STATE $\Gamma_{t+1}, \gamma_{t+1}, \theta_{t+1}= \textnormal{CalculateOriginalLearningRates}(\dots)$
\FOR{$i = 1, \dots, n$ in parallel}
\STATE $y^{t+1} = \theta_{t+1} {u^t} + (1 - \theta_{t+1}) z^t$ \label{line:adiana:y}
\STATE $m_i^{t,y} = \mathcal{C}_i^{D, y}(\nabla f_i(y^{t+1}) - h_i^t)$  \hfill{\scriptsize \color{gray} Worker $i$ compresses the shifted gradient via the compressor $\mathcal{C}_i^{D, y} \in \mathbb{U}(\omega)$}
\STATE {Send compressed message $m_i^{t,y}$ to the server}
\ENDFOR
\STATE $m^{t,y} = \frac{1}{n}\sum_{i = 1}^n m_i^{t,y}$ \hfill{\scriptsize \color{gray}Server averages the messages}
\STATE $g^{t+1} = h^t + m^{t,y} \equiv \frac{1}{n}\sum_{i=1}^n \left(h_i^t + m_i^{t,y}\right)$ 
\STATE $u^{t+1} = arg\,min_{x \in \mathbb{R}^d} \inp{g^{t+1}}{x} + \frac{\bar{L} + \Gamma_{t} \mu}{2 \gamma_{t+1}} \norm{x - u^t}^2 + \frac{\mu}{2} \norm{x - y^{t+1}}^2$ \hfill{\scriptsize \color{gray} Server does a gradient-like descent step} \label{line:adiana:u}
\STATE Flip a coin $c^t \sim \textnormal{Bernoulli}(p)$
\STATE {\color{mydarkred} Broadcast non-compressed messages $u^{t+1}$ to all $n$ workers} \label{line:adiana:broadcast}
\FOR{$i = 1, \dots, n$ in parallel}
\STATE $x^{t+1} = \theta_{t+1} u^{t+1} + (1 - \theta_{t+1}) z^t$ \label{line:adiana:x}
\STATE $z^{t+1} = \begin{cases}
  x^{t+1}, &c^t = 1 \\
  z^{t}, &c^t = 0
\end{cases}$ \label{line:adiana:z}
\STATE $m_i^{t,z} = \mathcal{C}_i^{D, z}(\nabla f_i(z^{t+1}) - h_i^t)$  \hfill{\scriptsize \color{gray} Worker $i$ compresses the shifted gradient via the compressor $\mathcal{C}_i^{D, z} \in \mathbb{U}(\omega)$}
\STATE $h_i^{t+1} = h_i^t + \beta m_i^{t,z}$ \hfill{\scriptsize \color{gray} Update the control variables}
\STATE {Send compressed message $m_i^{t,z}$ to the server}
\ENDFOR
\STATE $h^{t+1} = h^t + \beta \frac{1}{n} \sum_{i=1}^n m_i^{t,z}$ \hfill{\scriptsize \color{gray}Server averages the messages}
\ENDFOR
\end{algorithmic}

\caption{\algname{EF21-P + DIANA} by \citet{gruntkowska2022ef21}}
\footnotesize
\begin{algorithmic}[1]
\label{algorithm:diana_ef21_p}
\STATE \textbf{Parameters:} learning rates $\gamma > 0$ and $\beta > 0,$ initial model $u^0 \in \mathbb{R}^d,$ initial gradient shifts $h^0_1, \dots , h^0_n\in \mathbb{R}^d,$ average of the initial gradient shifts $h^0 = \frac{1}{n}\sum_{i = 1}^n h_i^0,$ initial model shift $w^0 = u^0\in \mathbb{R}^d$
\FOR{$t = 0, 1, \dots, T - 1$} 
\FOR{$i = 1, \dots, n$ in parallel} 
\STATE $m_i^t = \mathcal{C}_i^{D}(\nabla f_i(w^t) - h_i^t)$  \hfill{\scriptsize \color{gray} Worker $i$ compresses the shifted gradient via the dual compressor $\mathcal{C}_i^{D} \in \mathbb{U}(\omega)$}
\STATE {Send compressed message $m_i^t$ to the server}
\STATE $h^{t+1}_i = h^t_i + \beta m^t_i$ \hfill{\scriptsize \color{gray} Worker $i$ updates its local gradient shift with stepsize $\beta$}
\ENDFOR
\STATE $m^t = \frac{1}{n}\sum_{i = 1}^n m_i^t$ \hfill{\scriptsize \color{gray}Server averages the $n$ messages received from the workers}
\STATE $h^{t+1} = h^t + \beta m^t$ \hfill{\scriptsize \color{gray} Server updates the average gradient shift so that $h^t = \frac{1}{n}\sum_{i = 1}^n h_i^t$}
\STATE $g^{t} = h^t + m^t$ \hfill{\scriptsize \color{gray} Server computes the gradient estimator}
\STATE $u^{t+1} = u^t - \gamma g^t$ \hfill{\scriptsize \color{gray} Server takes a gradient-type step with stepsize $\gamma$}
\STATE {\color{mydarkgreen} $p^{t+1} = \mathcal{C}^{P}\left(u^{t+1} - w^t\right)$  \hfill {\scriptsize \color{gray} Server compresses the shifted model   via the primal compressor $\mathcal{C}^{P} \in \mathbb{B}\left(\alpha\right)$}} \label{line:adiana:ef21_p_1}
\STATE {\color{mydarkgreen} $w^{t+1} = w^t + p^{t+1}$\hfill{\scriptsize \color{gray}Server updates the model shift}} \label{line:adiana:ef21_p_2}
\STATE {\color{mydarkgreen} Broadcast compressed message $p^{t+1}$ to all $n$ workers} \label{line:adiana:ef21_p_3}
\FOR{$i = 1, \dots, n$ in parallel}
\STATE {\color{mydarkgreen} $w^{t+1} = w^{t} + p^{t+1}$ \hfill{\scriptsize \color{gray} Worker $i$ updates its local copy of the model shift}} \label{line:adiana:ef21_p_4}
\ENDFOR
\ENDFOR
