\end{align*}

\begin{align}
  \label{eq:theta_ineq}
  \theta_{t+1} \geq \min\left\{\max\left\{\sqrt{\frac{1}{4 p \Gamma_t}}, \sqrt{\frac{\mu}{4 p \bar{L}}}\right\}, \theta_{\min}\right\}.
\end{align}

\begin{align}
  \label{eq:gamma_ineq}
  \gamma_{t+1} := p \theta_{t+1} \Gamma_t / (1 - p \theta_{t+1}) \geq p \theta_{t+1} \Gamma_t \left(1 + p \theta_{t+1}\right)
\end{align}

\begin{align*}
  \Gamma_{t+1} := \Gamma_t + \gamma_{t+1} \geq \left(1 + p \theta_{t+1} + p^2 \theta_{t+1}^2\right) \Gamma_t.
\end{align*}

\begin{equation}
\begin{aligned}
  \label{eq:gamma_ineq_1}
  \Gamma_{t+1} &\geq \left(1 + p \min\left\{\sqrt{\frac{\mu}{4 p \bar{L}}}, \theta_{\min}\right\}\right) \Gamma_t = \left(1 + \min\left\{\sqrt{\frac{p \mu}{4 \bar{L}}}, p\theta_{\min}\right\}\right) \Gamma_t \\
  &\geq \Gamma_0 \left(1 + \min\left\{\sqrt{\frac{p \mu}{4 \bar{L}}}, p\theta_{\min}\right\}\right)^{t + 1} \geq \frac{\Gamma_0}{2}\exp\left((t + 1) \min\left\{\sqrt{\frac{p \mu}{4 \bar{L}}}, p\theta_{\min}\right\}\right),
\end{aligned}
\end{equation}

\begin{align*}
  \Gamma_{t+1} &\geq \left(1 + p \theta_{t+1} + p^2 \theta_{t+1}^2\right) \Gamma_t \\
  &\geq \Gamma_t + p\min\left\{\sqrt{\frac{1}{4 p \Gamma_t}}, \theta_{\min}\right\} \Gamma_t + p^2\min\left\{\sqrt{\frac{1}{4 p \Gamma_t}}, \theta_{\min}\right\}^2 \Gamma_t.
\end{align*}

\begin{align}
  \label{eq:gamma_first}
  \Gamma_{t+1} \geq \Gamma_t + p \theta_{\min} \Gamma_t + p^2 \theta_{\min}^2 \Gamma_t \geq \Gamma_t + p \theta_{\min} \Gamma_t \geq \Gamma_0 \left(1 + p \theta_{\min}\right)^{t+1} \geq \frac{\Gamma_0}{2} \exp \left((t+1) p \theta_{\min}\right).
\end{align}

\begin{align*}
  \frac{1}{4 p \theta_{\min}^2} > \Gamma_{\widehat{t} - 1} \geq \frac{\Gamma_0}{2} \exp \left((\widehat{t} - 1) p \theta_{\min}\right).
\end{align*}

\begin{align*}
  \widehat{t} \leq \bar{t} := \max\left\{\left\lceil\frac{1}{p \theta_{\min}} \log \frac{1}{2 \Gamma_0 p \theta_{\min}^2}\right\rceil, 0\right\}.
\end{align*}

\begin{align*}
  \Gamma_{t+1} \geq \Gamma_t + p\sqrt{\frac{1}{4 p \Gamma_t}} \Gamma_t + p^2 \frac{1}{4 p \Gamma_t} \Gamma_t = \Gamma_t + \sqrt{\frac{p}{4}} \sqrt{\Gamma_t} + \frac{p}{4}.
\end{align*}

\begin{align}
  \label{eq:gamma_second}
