\end{align}

\begin{align*}
  \Gamma_{t+1} &\geq \Gamma_t + \frac{\sqrt{p}}{2} \sqrt{\Gamma_t} + \frac{p}{4}\\
  &\geq \frac{1}{4 p \theta_{\min}^2} + \frac{p (t - \widehat{t})^2}{16} + \frac{\sqrt{p}}{2} \sqrt{\frac{1}{4 p \theta_{\min}^2} + \frac{p (t - \widehat{t})^2}{16}} + \frac{p}{4}\\
  &\geq \frac{1}{4 p \theta_{\min}^2} + \frac{p (t - \widehat{t})^2}{16} + \frac{p (t - \widehat{t})}{8} + \frac{p}{4}\\
  &\geq \frac{1}{4 p \theta_{\min}^2} + \frac{p (t - \widehat{t} + 1)^2}{16}.
\end{align*}

\begin{align*}
  \Gamma_{t} &\geq \min\left\{\frac{\Gamma_0}{2} \exp \left(t p \theta_{\min}\right), \frac{1}{4 p \theta_{\min}^2} + \frac{p (t - \widehat{t})^2}{16}\right\}
\end{align*}

\begin{align}
  \label{eq:aux_gamma_min}
  \Gamma_{t} &\geq \begin{cases}
    \frac{\Gamma_0}{2} \exp \left(t p \theta_{\min}\right), &t < \bar{t} \\
    \min\left\{\frac{\Gamma_0}{2} \exp \left(t p \theta_{\min}\right), \frac{1}{4 p \theta_{\min}^2} + \frac{p (t - \widehat{t})^2}{16}\right\}, &t \geq \bar{t}.
