    \min\left\{\frac{\Gamma_0}{2} \exp \left(t p \theta_{\min}\right), \frac{1}{4 p \theta_{\min}^2} + \frac{p (t - \bar{t})^2}{16}\right\}, &t \geq \bar{t}.
  \end{cases}
\end{align*}

\begin{align*}
  \frac{\Gamma_0}{2} \exp \left(t p \theta_{\min}\right) &\geq \frac{\Gamma_0}{2} \exp \left(\bar{t} p \theta_{\min}\right) + \frac{\Gamma_0}{2} p^2 \theta_{\min}^2 \exp \left(\bar{t} p \theta_{\min}\right) \frac{(t - \bar{t})^2}{2}\\
